import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { toast } from "sonner";
import { FaHome, FaUserGraduate, FaBuilding, FaShieldAlt } from "react-icons/fa";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Card } from "../components/ui/card";
import loginImage from "../assets/login.jpg";
import { useAuth } from "../context/AuthContext";

const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

const LoginPage = () => {
    const [userType, setUserType] = useState("student");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [logoFailed, setLogoFailed] = useState(false);
    const { loginAsDemo } = useAuth();
    const navigate = useNavigate();

    const handleRoleSelect = (role) => setUserType(role);

    const handleQuickDemoLogin = (role) => {
        const demoUser = loginAsDemo(role);
        toast.success(`Logged in as ${demoUser.name} (${role.toUpperCase()})`);
        if (role === "admin") {
            navigate("/admin/dashboard", { replace: true });
        } else if (role === "owner") {
            navigate("/owner/rooms", { replace: true });
        } else {
            navigate("/homepage", { replace: true });
        }
    };

    const handleLogin = async (e) => {
        e.preventDefault();
        toast.dismiss();

        if (!email.trim()) {
            toast.error("Email is required.");
            return;
        }
        if (!password) {
            toast.error("Password is required.");
            return;
        }

        setIsLoading(true);
        setTimeout(() => {
            const demoUser = loginAsDemo(userType);
            setIsLoading(false);
            toast.success(`Welcome back, ${demoUser.name}!`);
            if (userType === "admin") {
                navigate("/admin/dashboard", { replace: true });
            } else if (userType === "owner") {
                navigate("/owner/rooms", { replace: true });
            } else {
                navigate("/homepage", { replace: true });
            }
        }, 300);
    };

    const loginButtonText = `LOGIN AS ${userType.toUpperCase()}`;
    const backgroundImageUrl = loginImage;

    return (
        <div
            className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden"
            style={{ background: "linear-gradient(135deg, #A9BA9D 0%, #7F9C7F 25%, #547E61 50%, #2A6043 75%, #004225 100%)" }}
        >
            <div className="absolute inset-0 pointer-events-none bg-gradient-to-br from-white/[0.05] to-white/[0.01]" />

            <Card className="w-full max-w-5xl overflow-hidden rounded-2xl shadow-xl border border-gray-200 bg-white flex flex-col md:flex-row py-0">
                <div
                    className="md:w-1/2 relative flex flex-col justify-end rounded-l-2xl overflow-hidden bg-cover bg-center bg-no-repeat"
                    style={{ backgroundImage: `url(${backgroundImageUrl})`, minHeight: "400px" }}
                >
                    <div className="absolute inset-0 bg-black/50" />
                    <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_20%_20%,rgba(255,255,255,0.4),transparent_40%)]" />

                    <div className="relative z-10 p-8 md:p-10 text-white">
                        <div>
                            <h1 className="text-3xl md:text-4xl font-bold leading-tight tracking-tight">
                                Find Your
                                <br />
                                Perfect Student
                                <br />
                                Accommodation
                            </h1>
                            <p className="text-sm md:text-base opacity-90 mt-4">
                                The simplest way to discover rooms and mess services near your university.
                            </p>
                        </div>
                    </div>
                </div>

                <div className="md:w-1/2 p-6 md:p-10 rounded-r-2xl flex flex-col justify-center">
                    <div className="space-y-6">
                        <div className="w-20 h-20 bg-white/20 rounded-lg flex items-center justify-center mx-auto shadow-md">
                            {!logoFailed ? (
                                <img
                                    src={require("../assets/logo.png")}
                                    alt="Logo"
                                    className="w-20 h-20 object-cover rounded-lg"
                                    onError={() => setLogoFailed(true)}
                                />
                            ) : (
                                <FaHome className="w-10 h-10 text-primary" />
                            )}
                        </div>

                        <div>
                            <h2 className="text-2xl font-bold text-gray-800 text-center">
                                Welcome Back!
                            </h2>
                            <p className="text-muted-foreground text-xs text-center mt-1">
                                Find your student housing or explore using 1-click demo roles below.
                            </p>
                        </div>

                        {/* ===== 1-CLICK QUICK DEMO ACCESS CHIPS ===== */}
                        <div className="p-3.5 bg-emerald-50/80 border border-emerald-200 rounded-xl">
                            <p className="text-xs font-semibold text-emerald-900 mb-2.5 text-center uppercase tracking-wider">
                                ⚡ 1-Click Quick Demo Login
                            </p>
                            <div className="grid grid-cols-3 gap-2">
                                <Button
                                    type="button"
                                    size="sm"
                                    variant="outline"
                                    onClick={() => handleQuickDemoLogin('student')}
                                    className="bg-white hover:bg-emerald-100/60 border-emerald-300 text-emerald-900 text-xs font-medium h-9 flex items-center justify-center gap-1.5 shadow-sm"
                                >
                                    <FaUserGraduate className="text-emerald-700 text-xs" />
                                    Student
                                </Button>
                                <Button
                                    type="button"
                                    size="sm"
                                    variant="outline"
                                    onClick={() => handleQuickDemoLogin('owner')}
                                    className="bg-white hover:bg-emerald-100/60 border-emerald-300 text-emerald-900 text-xs font-medium h-9 flex items-center justify-center gap-1.5 shadow-sm"
                                >
                                    <FaBuilding className="text-emerald-700 text-xs" />
                                    Owner
                                </Button>
                                <Button
                                    type="button"
                                    size="sm"
                                    variant="outline"
                                    onClick={() => handleQuickDemoLogin('admin')}
                                    className="bg-white hover:bg-emerald-100/60 border-emerald-300 text-emerald-900 text-xs font-medium h-9 flex items-center justify-center gap-1.5 shadow-sm"
                                >
                                    <FaShieldAlt className="text-emerald-700 text-xs" />
                                    Admin
                                </Button>
                            </div>
                        </div>

                        <div className="relative flex py-1 items-center">
                            <div className="flex-grow border-t border-gray-200"></div>
                            <span className="flex-shrink mx-3 text-gray-400 text-xs font-medium uppercase">Or Sign In with Email</span>
                            <div className="flex-grow border-t border-gray-200"></div>
                        </div>

                        <form onSubmit={handleLogin} className="space-y-4">
                            <div>
                                <Label htmlFor="email" className="text-xs font-medium text-gray-600 block mb-1 uppercase">
                                    Email
                                </Label>
                                <Input
                                    id="email"
                                    type="email"
                                    placeholder="Enter your Email (e.g. demo@dormdish.com)"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    required
                                    className={`h-10 px-4 text-sm bg-gray-50 text-gray-800 placeholder-gray-500 rounded-lg ${
                                        email && !validateEmail(email) ? 'border-red-500 focus:border-red-500' : 'border-gray-300'
                                    }`}
                                />
                            </div>

                            <div>
                                <div className="flex justify-between items-center mb-1">
                                    <Label htmlFor="password" className="text-xs font-medium text-gray-600 uppercase">
                                        Password
                                    </Label>
                                    <Link to="/forgot-password" className="text-xs text-primary hover:text-primary/80 font-medium">
                                        Forgot password?
                                    </Link>
                                </div>
                                <Input
                                    id="password"
                                    type="password"
                                    placeholder="password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    required
                                    className="h-10 px-4 text-sm bg-gray-50 border-gray-300 text-gray-800 placeholder-gray-500 rounded-lg"
                                />
                            </div>

                            <div>
                                <div className="grid grid-cols-3 gap-2">
                                    {["student", "owner", "admin"].map((role) => (
                                        <Button
                                            key={role}
                                            type="button"
                                            variant={userType === role ? "default" : "outline"}
                                            className="h-9 text-xs font-medium capitalize rounded-lg"
                                            onClick={() => handleRoleSelect(role)}
                                        >
                                            {role}
                                        </Button>
                                    ))}
                                </div>
                            </div>

                            <Button
                                type="submit"
                                disabled={isLoading}
                                className="w-full h-10 font-medium text-sm rounded-lg"
                            >
                                {isLoading ? (
                                    <>
                                        <span className="mr-2 h-4 w-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                        Signing In...
                                    </>
                                ) : loginButtonText}
                            </Button>

                            <p className="text-center text-xs text-muted-foreground mt-3">
                                Don't have an account?{" "}
                                <Link to="/signup" className="text-primary hover:text-primary/80 font-medium">
                                    Sign up
                                </Link>
                            </p>
                        </form>
                    </div>
                </div>
            </Card>
        </div>
    );
};

export default LoginPage;
